     1	package com.example.order.common;
     2	
     3	import org.slf4j.Logger;
     4	import org.slf4j.LoggerFactory;
     5	import org.springframework.http.HttpHeaders;
     6	import org.springframework.http.HttpStatus;
     7	import org.springframework.http.HttpStatusCode;
     8	import org.springframework.http.MediaType;
     9	import org.springframework.http.ProblemDetail;
    10	import org.springframework.http.ResponseEntity;
    11	import java.util.stream.Collectors;
    12	import org.springframework.web.bind.MethodArgumentNotValidException;
    13	import org.springframework.web.bind.annotation.ExceptionHandler;
    14	import org.springframework.web.bind.annotation.RestControllerAdvice;
    15	import org.springframework.web.context.request.WebRequest;
    16	import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
    17	
    18	/** Every error becomes RFC 9457 application/problem+json with type, title, status, detail, code. */
    19	@RestControllerAdvice
    20	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
    21	
    22	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
    23	
    24	    @ExceptionHandler(ApiException.class)
    25	    public ResponseEntity<Object> handleApi(ApiException e) {
    26	        return problem(e.getStatus(), e.getCode(), e.getMessage(), null);
    27	    }
    28	
    29	    @ExceptionHandler(Exception.class)
    30	    public ResponseEntity<Object> handleUnexpected(Exception e) {
    31	        log.error("Unexpected error", e);
    32	        return problem(HttpStatus.INTERNAL_SERVER_ERROR, "INTERNAL_ERROR", "Unexpected server error", null);
    33	    }
    34	
    35	    /** Spring MVC's own exceptions (parse errors, missing params, type mismatch, 404/405/415 ...). */
    36	    @Override
    37	    protected ResponseEntity<Object> handleExceptionInternal(Exception ex, Object body, HttpHeaders headers,
    38	            HttpStatusCode statusCode, WebRequest request) {
    39	        String detail = null;
    40	        if (ex instanceof MethodArgumentNotValidException manv) {
    41	            detail = manv.getBindingResult().getFieldErrors().stream()
    42	                    .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
    43	                    .collect(Collectors.joining(", "));
    44	        } else if (body instanceof ProblemDetail pd) {
    45	            detail = pd.getDetail();
    46	        }
    47	        if (detail == null || detail.isBlank()) {
    48	            detail = ex.getMessage() != null ? ex.getMessage() : "Request failed";
    49	        }
    50	        String code = statusCode.value() == 400 ? "VALIDATION_ERROR" : codeFor(statusCode);
    51	        return problem(statusCode, code, detail, headers);
    52	    }
    53	
    54	    private static String codeFor(HttpStatusCode statusCode) {
    55	        HttpStatus s = HttpStatus.resolve(statusCode.value());
    56	        return s != null ? s.name() : "ERROR";
    57	    }
    58	
    59	    private static ResponseEntity<Object> problem(HttpStatusCode status, String code, String detail,
    60	            HttpHeaders headers) {
    61	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
    62	        HttpStatus resolved = HttpStatus.resolve(status.value());
    63	        pd.setTitle(resolved != null ? resolved.getReasonPhrase() : "Error");
    64	        pd.setProperty("code", code);
    65	        HttpHeaders out = new HttpHeaders();
    66	        if (headers != null) {
    67	            out.putAll(headers);
    68	        }
    69	        out.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
    70	        return new ResponseEntity<>(pd, out, status);
    71	    }
    72	}
