     3	import java.time.Instant;
     4	import java.time.OffsetDateTime;
     5	import java.time.ZoneOffset;
     6	import java.time.temporal.ChronoUnit;
     7	
     8	/** PostgreSQL timestamptz has microsecond precision; keep every timestamp at that precision in UTC. */
     9	public final class Times {
    10	
    11	    private Times() {
    12	    }
    13	
    14	    public static OffsetDateTime now() {
    15	        return Instant.now().truncatedTo(ChronoUnit.MICROS).atOffset(ZoneOffset.UTC);
    16	    }
    17	
    18	    public static OffsetDateTime normalize(OffsetDateTime t) {
    19	        return t.toInstant().truncatedTo(ChronoUnit.MICROS).atOffset(ZoneOffset.UTC);
    20	    }
    21	
    22	    public static long toEpochMicros(OffsetDateTime t) {
    23	        Instant i = t.toInstant();
    24	        return Math.addExact(Math.multiplyExact(i.getEpochSecond(), 1_000_000L), i.getNano() / 1_000L);
    25	    }
    26	
    27	    public static OffsetDateTime fromEpochMicros(long micros) {
    28	        return Instant.EPOCH.plus(micros, ChronoUnit.MICROS).atOffset(ZoneOffset.UTC);
    29	    }
    30	}
