     1	package com.example.order.coupon;
     2	
     3	import java.time.OffsetDateTime;
     4	
     5	public record Coupon(String code, String type, long value, long minOrderAmount, Long maxDiscountAmount,
     6	        long totalQuantity, long usedCount, OffsetDateTime validFrom, OffsetDateTime validUntil) {
     7	
     8	    /** R2.4: FIXED = value, RATE = floor(subtotal * value / 100); cap by maxDiscountAmount, then by subtotal. */
     9	    public long discountFor(long subtotal) {
    10	        long discount = "FIXED".equals(type) ? value : Math.floorDiv(Math.multiplyExact(subtotal, value), 100L);
    11	        if (maxDiscountAmount != null) {
    12	            discount = Math.min(discount, maxDiscountAmount);
    13	        }
    14	        return Math.min(discount, subtotal);
    15	    }
    16	
    17	    /** validFrom <= now < validUntil */
    18	    public boolean isValidAt(OffsetDateTime now) {
    19	        return !now.isBefore(validFrom) && now.isBefore(validUntil);
    20	    }
    21	}
