    20	@RestController
    21	@RequestMapping("/api/coupons")
    22	public class CouponController {
    23	
    24	    private final CouponRepository coupons;
    25	    private final ExpiryService expiry;
    26	
    27	    public CouponController(CouponRepository coupons, ExpiryService expiry) {
    28	        this.coupons = coupons;
    29	        this.expiry = expiry;
    30	    }
    31	
    32	    public record CreateCouponRequest(
    33	            @NotNull @Pattern(regexp = "^[A-Z0-9]{4,20}$") String code,
    34	            @NotNull @Pattern(regexp = "^(FIXED|RATE)$") String type,
    35	            @NotNull @Min(1) Long value,
    36	            @Min(0) Long minOrderAmount,
    37	            @Min(1) Long maxDiscountAmount,
    38	            @NotNull @Min(1) Long totalQuantity,
    39	            @NotNull OffsetDateTime validFrom,
    40	            @NotNull OffsetDateTime validUntil) {
    41	    }
    42	
    43	    public record CouponResponse(String code, String type, long value, long minOrderAmount, Long maxDiscountAmount,
    44	            long totalQuantity, long usedCount, OffsetDateTime validFrom, OffsetDateTime validUntil) {
    45	        static CouponResponse from(Coupon c) {
    46	            return new CouponResponse(c.code(), c.type(), c.value(), c.minOrderAmount(), c.maxDiscountAmount(),
    47	                    c.totalQuantity(), c.usedCount(), c.validFrom(), c.validUntil());
    48	        }
    49	    }
    50	
    51	    @PostMapping
    52	    public ResponseEntity<CouponResponse> create(@Valid @RequestBody CreateCouponRequest req) {
    53	        if ("RATE".equals(req.type()) && req.value() > 100) {
    54	            throw ApiException.validation("RATE coupon value must be between 1 and 100");
    55	        }
    56	        OffsetDateTime from = Times.normalize(req.validFrom());
    57	        OffsetDateTime until = Times.normalize(req.validUntil());
    58	        if (!from.isBefore(until)) {
    59	            throw ApiException.validation("validFrom must be before validUntil");
    60	        }
    61	        Coupon coupon = new Coupon(req.code(), req.type(), req.value(),
    62	                req.minOrderAmount() == null ? 0L : req.minOrderAmount(), req.maxDiscountAmount(),
    63	                req.totalQuantity(), 0L, from, until);
    64	        if (!coupons.insert(coupon)) {
    65	            throw ApiException.conflict("DUPLICATE_COUPON_CODE", "coupon " + req.code() + " already exists");
    66	        }
    67	        return ResponseEntity.created(URI.create("/api/coupons/" + coupon.code())).body(CouponResponse.from(coupon));
    68	    }
    69	
    70	    @GetMapping("/{code}")
    71	    public CouponResponse get(@PathVariable String code) {
    72	        expiry.expireDue();
    73	        return coupons.find(code).map(CouponResponse::from)
    74	                .orElseThrow(() -> ApiException.notFound("COUPON_NOT_FOUND", "coupon " + code + " not found"));
    75	    }
    76	}
