    10	@Repository
    11	public class CouponRepository {
    12	
    13	    private static final String COLS = "code, type, value, min_order_amount, max_discount_amount, total_quantity, "
    14	            + "used_count, valid_from, valid_until";
    15	
    16	    private static final RowMapper<Coupon> MAPPER = (rs, i) -> new Coupon(
    17	            rs.getString("code"), rs.getString("type"), rs.getLong("value"), rs.getLong("min_order_amount"),
    18	            (Long) rs.getObject("max_discount_amount", Long.class), rs.getLong("total_quantity"),
    19	            rs.getLong("used_count"), rs.getObject("valid_from", OffsetDateTime.class),
    20	            rs.getObject("valid_until", OffsetDateTime.class));
    21	
    22	    private final JdbcTemplate jdbc;
    23	
    24	    public CouponRepository(JdbcTemplate jdbc) {
    25	        this.jdbc = jdbc;
    26	    }
    27	
    28	    /** @return false when the code already exists */
    29	    public boolean insert(Coupon c) {
    30	        int n = jdbc.update("INSERT INTO coupons (" + COLS + ") VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?) "
    31	                        + "ON CONFLICT (code) DO NOTHING",
    32	                c.code(), c.type(), c.value(), c.minOrderAmount(), c.maxDiscountAmount(), c.totalQuantity(),
    33	                c.validFrom(), c.validUntil());
    34	        return n == 1;
    35	    }
    36	
    37	    public Optional<Coupon> find(String code) {
    38	        List<Coupon> rows = jdbc.query("SELECT " + COLS + " FROM coupons WHERE code = ?", MAPPER, code);
    39	        return rows.stream().findFirst();
    40	    }
    41	
    42	    public Coupon lock(String code) {
    43	        return jdbc.queryForObject("SELECT " + COLS + " FROM coupons WHERE code = ? FOR UPDATE", MAPPER, code);
    44	    }
    45	
    46	    public void addUsed(String code, long delta) {
    47	        jdbc.update("UPDATE coupons SET used_count = used_count + ? WHERE code = ?", delta, code);
    48	    }
    49	}
