     1	package com.example.order.idempotency;
     2	
     3	import com.example.order.common.ApiException;
     4	import java.nio.charset.StandardCharsets;
     5	import java.security.MessageDigest;
     6	import java.util.HexFormat;
     7	import java.util.List;
     8	import java.util.Optional;
     9	import org.springframework.http.HttpStatus;
    10	import org.springframework.jdbc.core.JdbcTemplate;
    11	import org.springframework.stereotype.Service;
    12	
    13	/**
    14	 * Idempotency-Key store (R4). A key is claimed by inserting an IN_PROGRESS row in its own (auto-committed)
    15	 * statement; the business transaction turns it into DONE with the response snapshot; failures delete the row so the
    16	 * same request can be retried (only 2xx responses are stored).
    17	 */
    18	@Service
    19	public class IdempotencyService {
    20	
    21	    public static final String SCOPE_CREATE_ORDER = "CREATE_ORDER";
    22	    public static final String SCOPE_PAY = "PAY";
    23	
    24	    public record StoredResponse(int status, String body, String location) {
    25	    }
    26	
    27	    private record Row(String fingerprint, String state, Integer status, String body, String location) {
    28	    }
    29	
    30	    private final JdbcTemplate jdbc;
    31	
    32	    public IdempotencyService(JdbcTemplate jdbc) {
    33	        this.jdbc = jdbc;
    34	    }
    35	
    36	    /**
    37	     * @return empty when this caller now owns the key and must process the request; otherwise the stored response
    38	     * to replay. Throws 422 on fingerprint mismatch and 409 while another request with the key is in flight.
    39	     */
    40	    public Optional<StoredResponse> begin(String scope, String key, String fingerprint) {
    41	        while (true) {
    42	            int inserted = jdbc.update("INSERT INTO idempotency_keys (scope, idem_key, fingerprint, state) "
    43	                    + "VALUES (?, ?, ?, 'IN_PROGRESS') ON CONFLICT (scope, idem_key) DO NOTHING",
    44	                    scope, key, fingerprint);
    45	            if (inserted == 1) {
    46	                return Optional.empty();
    47	            }
    48	            List<Row> rows = jdbc.query("SELECT fingerprint, state, response_status, response_body, location "
    49	                            + "FROM idempotency_keys WHERE scope = ? AND idem_key = ?",
    50	                    (rs, i) -> new Row(rs.getString(1), rs.getString(2), (Integer) rs.getObject(3, Integer.class),
    51	                            rs.getString(4), rs.getString(5)),
    52	                    scope, key);
    53	            if (rows.isEmpty()) {
    54	                continue; // the previous holder failed and released the key; try to claim it again
    55	            }
    56	            Row row = rows.get(0);
    57	            if (!row.fingerprint().equals(fingerprint)) {
    58	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "IDEMPOTENCY_KEY_MISMATCH",
    59	                        "Idempotency-Key was already used for a different request");
    60	            }
    61	            if ("DONE".equals(row.state())) {
    62	                return Optional.of(new StoredResponse(row.status(), row.body(), row.location()));
    63	            }
    64	            throw ApiException.conflict("IDEMPOTENCY_IN_PROGRESS",
    65	                    "a request with this Idempotency-Key is still being processed");
    66	        }
    67	    }
    68	
    69	    /** Called inside the business transaction so the snapshot commits atomically with the state change. */
    70	    public void complete(String scope, String key, int status, String body, String location) {
    71	        jdbc.update("UPDATE idempotency_keys SET state = 'DONE', response_status = ?, response_body = ?, "
    72	                + "location = ? WHERE scope = ? AND idem_key = ?", status, body, location, scope, key);
    73	    }
    74	
    75	    public void release(String scope, String key) {
    76	        jdbc.update("DELETE FROM idempotency_keys WHERE scope = ? AND idem_key = ? AND state = 'IN_PROGRESS'",
    77	                scope, key);
    78	    }
    79	
    80	    public static String fingerprint(String canonical) {
    81	        try {
    82	            MessageDigest md = MessageDigest.getInstance("SHA-256");
    83	            return HexFormat.of().formatHex(md.digest(canonical.getBytes(StandardCharsets.UTF_8)));
    84	        } catch (Exception e) {
    85	            throw new IllegalStateException(e);
    86	        }
    87	    }
    88	}
