     9	import org.springframework.transaction.PlatformTransactionManager;
    10	import org.springframework.transaction.TransactionDefinition;
    11	import org.springframework.transaction.support.TransactionTemplate;
    12	
    13	/**
    14	 * R6: PENDING_PAYMENT orders past expiresAt become EXPIRED. A sweeper runs every 500 ms, and reads call
    15	 * {@link #expireDue()} first so the change is visible as soon as possible. Each order is expired in its own
    16	 * transaction; rows locked by a concurrent payment/cancel are skipped (that path re-checks expiry itself).
    17	 */
    18	@Service
    19	public class ExpiryService {
    20	
    21	    private static final Logger log = LoggerFactory.getLogger(ExpiryService.class);
    22	
    23	    private final OrderRepository orders;
    24	    private final ReservationReleaser releaser;
    25	    private final TransactionTemplate tx;
    26	
    27	    public ExpiryService(OrderRepository orders, ReservationReleaser releaser, PlatformTransactionManager tm) {
    28	        this.orders = orders;
    29	        this.releaser = releaser;
    30	        this.tx = new TransactionTemplate(tm);
    31	        this.tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
    32	    }
    33	
    34	    @Scheduled(fixedDelay = 500, initialDelay = 500)
    35	    public void sweep() {
    36	        try {
    37	            expireDue();
    38	        } catch (Exception e) {
    39	            log.warn("expiry sweep failed", e);
    40	        }
    41	    }
    42	
    43	    public void expireDue() {
    44	        while (Boolean.TRUE.equals(tx.execute(s -> expireOne()))) {
    45	            // keep going until nothing is due
    46	        }
    47	    }
    48	
    49	    private boolean expireOne() {
    50	        List<Order> due = orders.lockExpired(Times.now(), 1);
    51	        if (due.isEmpty()) {
    52	            return false;
    53	        }
    54	        expire(due.get(0));
    55	        return true;
    56	    }
    57	
    58	    /** Caller must hold the order row lock and be inside a transaction. */
    59	    public void expire(Order order) {
    60	        releaser.releaseReservation(order);
    61	        orders.updateStatus(order.id(), OrderStatus.EXPIRED);
    62	    }
