 58	            String path = ex.getRequestURI().getPath();
 59	            String body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
 60	            int status = 200;
 61	            String out;
 62	            if (path.endsWith("/refund")) {
 63	                String id = path.split("/")[3];
 64	                if ("fail".equals(refundMode.get())) {
 65	                    status = 500;
 66	                    out = "{}";
