 72	                String token = om.readTree(body).path("cardToken").asText();
 73	                String paymentId = "pay-" + UUID.randomUUID();
 74	                switch (token) {
 75	                    case "decline" -> out = "{\"paymentId\":\"" + paymentId + "\",\"status\":\"DECLINED\"}";
