486	    41	        while (true) {
487	    42	            int inserted = jdbc.update("INSERT INTO idempotency_keys (scope, idem_key, fingerprint, state) "
488	    43	                    + "VALUES (?, ?, ?, 'IN_PROGRESS') ON CONFLICT (scope, idem_key) DO NOTHING",
489	    44	                    scope, key, fingerprint);
