    69	    /** Called inside the business transaction so the snapshot commits atomically with the state change. */
    70	    public void complete(String scope, String key, int status, String body, String location) {
    71	        jdbc.update("UPDATE idempotency_keys SET state = 'DONE', response_status = ?, response_body = ?, "
    72	                + "location = ? WHERE scope = ? AND idem_key = ?", status, body, location, scope, key);
    73	    }
    74	
    75	    public void release(String scope, String key) {
    76	        jdbc.update("DELETE FROM idempotency_keys WHERE scope = ? AND idem_key = ? AND state = 'IN_PROGRESS'",
    77	                scope, key);
    78	    }
