    80	    public static String fingerprint(String canonical) {
    81	        try {
    82	            MessageDigest md = MessageDigest.getInstance("SHA-256");
    83	            return HexFormat.of().formatHex(md.digest(canonical.getBytes(StandardCharsets.UTF_8)));
    84	        } catch (Exception e) {
    85	            throw new IllegalStateException(e);
    86	        }
