     9	/** Opaque keyset cursor: base64url("{createdAt epoch micros}:{id}") of the last row of the previous page. */
    10	public record OrderCursor(OffsetDateTime createdAt, long id) {
    11	
    12	    public String encode() {
    13	        String raw = Times.toEpochMicros(createdAt) + ":" + id;
    14	        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8));
    15	    }
    16	
    17	    public static OrderCursor decode(String value) {
    18	        try {
    19	            String raw = new String(Base64.getUrlDecoder().decode(value), StandardCharsets.UTF_8);
    20	            int sep = raw.indexOf(':');
    21	            if (sep <= 0 || sep != raw.lastIndexOf(':')) {
    22	                throw new IllegalArgumentException("malformed cursor");
    23	            }
    24	            long micros = Long.parseLong(raw.substring(0, sep));
    25	            long id = Long.parseLong(raw.substring(sep + 1));
    26	            return new OrderCursor(Times.fromEpochMicros(micros), id);
    27	        } catch (RuntimeException e) {
    28	            throw ApiException.validation("cursor is invalid");
    29	        }
    30	    }
    31	}
