     1	package com.example.order.order;
     2	
     3	import com.example.order.coupon.CouponRepository;
     4	import com.example.order.product.ProductRepository;
     5	import java.util.Comparator;
     6	import org.springframework.stereotype.Component;
     7	
     8	/**
     9	 * Stock/coupon side effects of order transitions. Product rows are always touched in ascending id order and the coupon
    10	 * row last, matching the lock order used by order creation, so concurrent transitions cannot deadlock.
    11	 */
    12	@Component
    13	public class ReservationReleaser {
    14	
    15	    private final ProductRepository products;
    16	    private final CouponRepository coupons;
    17	
    18	    public ReservationReleaser(ProductRepository products, CouponRepository coupons) {
    19	        this.products = products;
    20	        this.coupons = coupons;
    21	    }
    22	
    23	    /** PENDING_PAYMENT -> CANCELLED / EXPIRED / PAYMENT_FAILED: drop reservations, give the coupon use back. */
    24	    public void releaseReservation(Order order) {
    25	        order.items().stream().sorted(Comparator.comparingLong(Order.Item::productId))
    26	                .forEach(i -> products.addReserved(i.productId(), -i.quantity()));
    27	        restoreCoupon(order);
    28	    }
    29	
    30	    /** PENDING_PAYMENT -> PAID: reserved units are sold. */
    31	    public void consumeReservation(Order order) {
    32	        order.items().stream().sorted(Comparator.comparingLong(Order.Item::productId))
    33	                .forEach(i -> products.consumeReserved(i.productId(), i.quantity()));
    34	    }
    35	
    36	    /** PAID -> REFUNDED: units go back to stock, coupon use is restored. */
    37	    public void returnStock(Order order) {
    38	        order.items().stream().sorted(Comparator.comparingLong(Order.Item::productId))
    39	                .forEach(i -> products.addStock(i.productId(), i.quantity()));
    40	        restoreCoupon(order);
    41	    }
    42	
    43	    private void restoreCoupon(Order order) {
    44	        if (order.couponCode() != null) {
    45	            coupons.addUsed(order.couponCode(), -1);
    46	        }
    47	    }
    48	}
