    20	/**
    21	 * External PG. Any 5xx, connection failure, 2-second timeout (whole exchange) or unusable response is reported as
    22	 * 503 PAYMENT_GATEWAY_UNAVAILABLE.
    23	 */
    24	@Component
    25	public class PaymentGatewayClient {
    26	
    27	    private static final Logger log = LoggerFactory.getLogger(PaymentGatewayClient.class);
    28	    static final Duration TIMEOUT = Duration.ofSeconds(2);
    29	
    30	    public enum PaymentStatus { APPROVED, DECLINED }
    31	
    32	    public record PaymentResult(String paymentId, PaymentStatus status) {
    33	    }
    34	
    35	    private final String baseUrl;
    36	    private final ObjectMapper mapper;
    37	    private final HttpClient http = HttpClient.newBuilder()
    38	            .version(HttpClient.Version.HTTP_1_1)
    39	            .connectTimeout(TIMEOUT)
    40	            .build();
    41	
    42	    public PaymentGatewayClient(@Value("${app.payment-gateway-url}") String baseUrl, ObjectMapper mapper) {
    43	        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    44	        this.mapper = mapper;
    45	    }
    46	
    47	    public PaymentResult pay(long orderId, long amount, String cardToken, String idempotencyKey) {
    48	        Map<String, Object> body = new LinkedHashMap<>();
    49	        body.put("orderId", orderId);
    50	        body.put("amount", amount);
    51	        body.put("cardToken", cardToken);
    52	        HttpRequest req;
    53	        try {
    54	            req = HttpRequest.newBuilder(URI.create(baseUrl + "/v1/payments"))
    55	                    .timeout(TIMEOUT)
    56	                    .header("Content-Type", "application/json")
    57	                    .header("Accept", "application/json")
    58	                    .header("Idempotency-Key", idempotencyKey)
    59	                    .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body)))
    60	                    .build();
    61	        } catch (Exception e) {
    62	            throw ApiException.gatewayUnavailable("payment gateway request could not be built");
    63	        }
    64	        JsonNode json = exchange(req);
    65	        String status = json.path("status").asText("");
    66	        String paymentId = json.path("paymentId").isMissingNode() || json.path("paymentId").isNull()
    67	                ? null : json.path("paymentId").asText();
    68	        return switch (status) {
    69	            case "APPROVED" -> new PaymentResult(paymentId, PaymentStatus.APPROVED);
    70	            case "DECLINED" -> new PaymentResult(paymentId, PaymentStatus.DECLINED);
    71	            default -> throw ApiException.gatewayUnavailable("payment gateway returned unknown status");
    72	        };
    73	    }
    74	
    75	    public void refund(String paymentId) {
    76	        HttpRequest req = HttpRequest.newBuilder(
    77	                        URI.create(baseUrl + "/v1/payments/" + encodePath(paymentId) + "/refund"))
    78	                .timeout(TIMEOUT)
    79	                .header("Accept", "application/json")
    80	                .POST(HttpRequest.BodyPublishers.noBody())
    81	                .build();
    82	        JsonNode json = exchange(req);
    83	        if (!"REFUNDED".equals(json.path("status").asText(""))) {
    84	            throw ApiException.gatewayUnavailable("payment gateway did not confirm the refund");
    85	        }
    86	    }
    87	
    88	    private JsonNode exchange(HttpRequest req) {
    89	        CompletableFuture<HttpResponse<String>> future = http.sendAsync(req, HttpResponse.BodyHandlers.ofString());
    90	        HttpResponse<String> res;
    91	        try {
    92	            res = future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
    93	        } catch (InterruptedException e) {
    94	            future.cancel(true);
    95	            Thread.currentThread().interrupt();
    96	            throw ApiException.gatewayUnavailable("payment gateway call interrupted");
    97	        } catch (Exception e) {
    98	            future.cancel(true);
    99	            log.warn("payment gateway call failed: {} {}", req.uri(), e.toString());
   100	            throw ApiException.gatewayUnavailable("payment gateway is unavailable");
   101	        }
   102	        if (res.statusCode() / 100 != 2) {
   103	            log.warn("payment gateway returned {} for {}", res.statusCode(), req.uri());
   104	            throw ApiException.gatewayUnavailable("payment gateway responded with status " + res.statusCode());
   105	        }
   106	        try {
   107	            return mapper.readTree(res.body());
   108	        } catch (Exception e) {
   109	            throw ApiException.gatewayUnavailable("payment gateway returned an unreadable response");
   110	        }
   111	    }
   112	
   113	    private static String encodePath(String segment) {
   114	        return java.net.URLEncoder.encode(segment, java.nio.charset.StandardCharsets.UTF_8).replace("+", "%20");
   115	    }
   116	}
