        return one("SELECT " + COLS + " FROM orders WHERE tenant_id = ? AND id = ? FOR UPDATE", tenantId, id);
    }

    private Optional<Order> one(String sql, String tenantId, long id) {
        List<Order> rows = jdbc.query(sql, MAPPER, tenantId, id);
