        Boolean b = jdbc.queryForObject("SELECT EXISTS (SELECT 1 FROM orders WHERE user_id = ? AND coupon_code = ? "
                        + "AND status IN ('PENDING_PAYMENT', 'PAID', 'SHIPPED', 'DELIVERED'))",
