    @Test
    void m8_oneUserOneCouponRaceHoldsInEveryTenant() throws Exception {
        String a = tenant();
        String b = tenant();
        assertThat(coupon(a, "SOLO0001", 10).status()).isEqualTo(201);
        assertThat(coupon(b, "SOLO0001", 10).status()).isEqualTo(201);
